-- Stub rows for anything the class references that the catalog lacks.
-- The "STUB" marker is load-bearing: it is how the gear importer later
-- recognises a row as still needing stats.
-- NOT a stub: the book names this armor and prints both of its numbers, so
-- the row carries them. Standard issue to a phase mystic, printed 29.
INSERT OR IGNORE INTO gear (slug, name, system, category, ar, mdc, description, source_book) VALUES ('steelcloth-robes-and-jumpsuit', 'Steelcloth Robes and Jumpsuit', 'rifts', 'armor', 19, 40, 'Loose-fitting steelcloth robes worn over a jumpsuit, the standard dress of a phase mystic. A.R. 19, 40 M.D.C. Distinct from the phase adept''s steelcloth robes, which are A.R. 12 and 90 M.D.C.', 'Rifts Dimension Book 2: Phase World p.29');
